# Read-only pinned method-operand scan. No inspected method is invoked.
param([Parameter(Mandatory)][string]$ModulePath)
$ErrorActionPreference='Stop'
if((Get-FileHash (Join-Path $ModulePath 'bin/Microsoft.Teams.ConfigAPI.Cmdlets.private.dll')).Hash.ToLowerInvariant() -ne '8b7ccef9361ee1ffeaf05b79a2638f6a6b8ace39bba034edc630e0415e95ccb6'){throw 'Wrong private assembly'}
Import-Module (Join-Path $ModulePath 'MicrosoftTeams.psd1') -Force -WarningAction SilentlyContinue
foreach($a in [AppDomain]::CurrentDomain.GetAssemblies()){try{$null=$a.GetTypes()}catch{}}
$types=@();foreach($a in [AppDomain]::CurrentDomain.GetAssemblies()){if($a.GetName().Name -eq 'Microsoft.Teams.ConfigAPI.Cmdlets.private'){$types=$a.GetTypes()}}
$targets=@('set_DefaultAutoRestParameters','set_InvocationInformation')
$opcodes=@{};foreach($f in [Reflection.Emit.OpCodes].GetFields([Reflection.BindingFlags]'Public,Static')){$op=$f.GetValue($null);$opcodes[[int]$op.Value -band 65535]=$op}
$rows=@();$bodiesScanned=0;$methodOperandsResolved=0;$resolveFailures=0;foreach($t in $types){foreach($m in @($t.GetMethods([Reflection.BindingFlags]'Instance,Static,Public,NonPublic,DeclaredOnly'))+@($t.GetConstructors([Reflection.BindingFlags]'Instance,Static,Public,NonPublic,DeclaredOnly'))){$b=$m.GetMethodBody();if(!$b){continue};$bodiesScanned++;$bytes=$b.GetILAsByteArray();$pos=0;while($pos -lt $bytes.Length){$start=$pos;$code=[int]$bytes[$pos++];if($code -eq 254){$code=65024+[int]$bytes[$pos++]};$op=$opcodes[$code];$kind=[string]$op.OperandType;$size=4;switch($kind){'InlineNone'{$size=0}'ShortInlineBrTarget'{$size=1}'ShortInlineI'{$size=1}'ShortInlineVar'{$size=1}'InlineVar'{$size=2}'InlineI8'{$size=8}'InlineR'{$size=8}'InlineSwitch'{$size=4+4*[BitConverter]::ToInt32($bytes,$pos)}};if($kind -eq 'InlineMethod'){try{$argsType=$t.GetGenericArguments();$argsMethod=if($m -is [Reflection.MethodInfo]){$m.GetGenericArguments()}else{@()};$called=$m.Module.ResolveMethod([BitConverter]::ToInt32($bytes,$pos),$argsType,$argsMethod);$methodOperandsResolved++;if($called.Name -in $targets){$rows+=@{type=$t.FullName;method=[string]$m;offset=$start;target=[string]$called.DeclaringType+'.'+[string]$called}}}catch{$resolveFailures++;throw}};$pos+=$size}}}
@{scope='Every InlineMethod operand in all declared method/constructor bodies of pinned private assembly; direct calls only, dynamic reflection inspected separately on selected handoff paths';types_scanned=$types.Count;bodies_scanned=$bodiesScanned;method_operands_resolved=$methodOperandsResolved;unresolved=$resolveFailures;target_names=$targets;callers=@($rows)}|ConvertTo-Json -Depth 6 -Compress
